const ids = $json.ids ?? [];
const metadatas = $json.metadatas ?? [];
let active = ids
  .map((code, i) => ({ code, ...(metadatas[i] || {}) }))
  .filter((entry) => entry.active !== false && entry.code);
if (active.length === 0) {
  // Fall back to the env-configured default so an empty watchlist doesn't
  // silently produce a no-op ingestion.
  const fallback = String($env.ARXIV_CATEGORIES || 'cs.AI').split(',').map((c) => c.trim()).filter(Boolean);
  active = fallback.map((code) => ({ code, maxResults: Number($env.ARXIV_MAX_RESULTS || 5) }));
}
return active.map((entry) => {
  const maxResults = Number(entry.maxResults ?? $env.ARXIV_MAX_RESULTS ?? 5);
  const url = `https://export.arxiv.org/api/query?search_query=cat:${encodeURIComponent(entry.code)}&start=0&max_results=${maxResults}&sortBy=submittedDate&sortOrder=descending`;
  return { json: { category: entry.code, maxResults, feedUrl: url } };
});

// One input item per watched category, from "Fetch arXiv feed". That node is
// allowed to fail per item (arXiv intermittently answers 406 to an address it
// has seen a lot of), so an item here is either a feed or an error.
//
// For any category that came back without papers, two independent sources
// are tried before giving up: the same API on arxiv.org, then the separate
// rss.arxiv.org announcement feed. Papers already in the vector store are
// then dropped, so a repeat run costs seconds rather than re-downloading and
// re-embedding everything, and does not add to the traffic that gets an
// address refused in the first place.
const helpers = this.helpers;
const feeds = $input.all();
const categories = $('Build feed URLs').all();
const chroma = $env.CHROMA_BASE_URL || 'http://chroma:8000';
const HEADERS = {
  'User-Agent': 'research-intelligence-bot/1.0 (n8n workflow)',
  Accept: 'application/atom+xml, application/xml;q=0.9, */*;q=0.8',
};

const clean = (s) => String(s)
  .replace(/<!\[CDATA\[|\]\]>/g, '')
  .replace(/<[^>]+>/g, '')
  .replace(/\s+/g, ' ')
  .trim();
const tag = (entry, name) =>
  clean(entry.match(new RegExp(`<${name}[^>]*>([\\s\\S]*?)<\\/${name}>`))?.[1] ?? '');

// Handles both shapes: the query API (id is an abs URL, has a pdf link) and
// the RSS announcement feed (id is oai:arXiv.org:<id>, summary is prefixed
// with "arXiv:<id> Announce Type: new Abstract: ...").
function parseEntries(xml, category, limit) {
  const out = [];
  for (const entry of String(xml).match(/<entry>[\s\S]*?<\/entry>/g) ?? []) {
    const rawId = tag(entry, 'id');
    const arxivId = rawId.split(/[/:]/).pop();
    if (!/^\d{4}\.\d{4,5}(v\d+)?$/.test(arxivId)) continue;
    let abstract = tag(entry, 'summary');
    if (rawId.startsWith('oai:')) {
      if (!/Announce Type:\s*new/i.test(abstract)) continue;   // skip replacements and cross-lists
      abstract = abstract.replace(/^.*?Abstract:\s*/i, '');
    }
    const pdfUrl = entry.match(/<link[^>]+title="pdf"[^>]+href="([^"]+)"/)?.[1]
      ?? `https://arxiv.org/pdf/${arxivId}`;
    out.push({
      arxivId,
      title: tag(entry, 'title'),
      abstract,
      published: tag(entry, 'published') || tag(entry, 'updated'),
      pdfUrl,
      category,
    });
    if (out.length >= limit) break;
  }
  return out;
}

const report = [];
const found = [];
for (let i = 0; i < categories.length; i += 1) {
  const { category, maxResults } = categories[i].json;
  const limit = Number(maxResults) || 5;
  const primary = feeds[i]?.json ?? {};
  const xml = primary.data ?? primary.body ?? '';
  let papers = typeof xml === 'string' ? parseEntries(xml, category, limit) : [];
  let source = 'export.arxiv.org';

  if (papers.length === 0) {
    const query = `search_query=cat:${encodeURIComponent(category)}&start=0&max_results=${limit}&sortBy=submittedDate&sortOrder=descending`;
    const alternates = [
      ['arxiv.org', `https://arxiv.org/api/query?${query}`],
      ['rss.arxiv.org', `https://rss.arxiv.org/atom/${encodeURIComponent(category)}`],
    ];
    source = 'unavailable';
    for (const [name, url] of alternates) {
      try {
        const body = await helpers.httpRequest({ url, headers: HEADERS, timeout: 45000, json: false });
        papers = parseEntries(body, category, limit);
        if (papers.length > 0) { source = name; break; }
      } catch (error) {
        // try the next source
      }
    }
  }
  report.push(`${category}: ${papers.length} from ${source}`);
  found.push(...papers);
}

// A paper cross-listed in two watched categories arrives twice.
const unique = Array.from(new Map(found.map((p) => [p.arxivId, p])).values());

// Drop what the vector store already holds. If the lookup itself fails the
// paper is kept: re-ingesting is harmless because the upsert is idempotent.
let collectionId = null;
try {
  const collection = await helpers.httpRequest({
    method: 'POST', url: `${chroma}/api/v1/collections`, json: true,
    body: { name: 'research_papers', get_or_create: true },
  });
  collectionId = collection.id;
} catch (error) {
  collectionId = null;
}

const fresh = [];
let alreadyIndexed = 0;
for (const paper of unique) {
  let exists = false;
  if (collectionId) {
    try {
      const hit = await helpers.httpRequest({
        method: 'POST', url: `${chroma}/api/v1/collections/${collectionId}/get`, json: true,
        body: { where: { arxivId: paper.arxivId }, limit: 1, include: ['metadatas'] },
      });
      exists = (hit.ids ?? []).length > 0;
    } catch (error) {
      exists = false;
    }
  }
  if (exists) alreadyIndexed += 1;
  else fresh.push(paper);
}

const feedReport = report.join(' | ');
console.log(`[ingestion] ${feedReport} | unique ${unique.length} | already indexed ${alreadyIndexed} | new ${fresh.length}`);
return fresh.map((paper) => ({ json: { ...paper, alreadyIndexed, feedReport } }));

const size = 1200;
const overlap = 180;
const maxChunksPerPaper = 24;   // ~10 pages; skips references and appendices
const papers = $('Normalise papers').all();
const chunks = [];
$input.all().forEach((item, i) => {
  const source = papers[i]?.json;
  if (!source) return;
  const text = String(item.json.text ?? item.json.data ?? '').replace(/\s+/g, ' ').trim();
  for (let start = 0, index = 0; start < text.length; start += size - overlap, index += 1) {
    if (index >= maxChunksPerPaper) break;
    // A cut can land inside a two-part character (common for maths symbols);
    // half of one is invalid text and the vector store rejects the chunk.
    const content = text.slice(start, start + size)
      .replace(/[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g, '');
    if (content.length >= 200) {
      chunks.push({ json: { ...source, chunk: content, chunkId: `${source.arxivId}-${index}` } });
    }
  }
});
return chunks;

const chunks = $('Chunk paper text').all();
// Positional match, then drop anything the embedder could not return a
// vector for. An empty embedding would otherwise be upserted and would sit
// in the corpus matching nothing.
return $input.all()
  .map((item, i) => ({
    json: { ...chunks[i].json, embedding: item.json.embeddings?.[0] ?? [] }
  }))
  .filter(item => Array.isArray(item.json.embedding) && item.json.embedding.length > 0);

const papers = $('Normalise papers').all().map((item) => item.json);
const uniq = new Map();
for (const p of papers) {
  if (!uniq.has(p.arxivId)) uniq.set(p.arxivId, p);
}
const unique = Array.from(uniq.values());
const categories = [...new Set(unique.map((p) => p.category).filter(Boolean))];
const MAX_ABSTRACT = 220;
const lines = unique.map((paper, index) => {
  const abstract = (paper.abstract || '').length > MAX_ABSTRACT ? `${paper.abstract.slice(0, MAX_ABSTRACT)}...` : (paper.abstract || '');
  return `${index + 1}. ${paper.title}\n   arXiv:${paper.arxivId} | ${paper.pdfUrl}\n   ${abstract}`;
}).join('\n\n');
const header = `Daily arXiv digest -- ${unique.length} paper(s) indexed today` + (categories.length ? ` from ${categories.join(', ')}` : '') + `\n\n`;
const skipped = papers[0]?.alreadyIndexed ?? 0;
const footer = skipped > 0 ? `\n\n(${skipped} more already indexed, skipped)` : '';
const digestText = (header + lines).slice(0, 3700).concat(footer)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{ json: { digestText, paperCount: unique.length, categoryCount: categories.length } }];

const digestText = $('Build daily digest').first().json.digestText;
const ids = $json.ids ?? [];
if (ids.length === 0) return [];
return ids.map((chatId) => ({ json: { chatId, digestText } }));
